def asignar_uso(apps, schema_editor):
    """Las listas que ya existen toman su uso del nombre; la principal es siempre el precio público."""
    ListaPrecio = apps.get_model("mantenimiento", "ListaPrecio")
    for lista in ListaPrecio.objects.all():
        uso = USOS_POR_NOMBRE.get(lista.nombre.strip().lower())
        if lista.es_principal:
            uso = "PUBLICO"
        if uso:
            ListaPrecio.objects.filter(pk=lista.pk).update(uso=uso)


